REPLAYABLE PRODUCTION DRILLS, no shared source mutations. Fullsourcebelow; saveas%TEMP%/backup-drill.mjs. cwdapps/daemon; setMOE_BACKUP_DRILL=mode; pnpm exec vitest run --root . --config <tempconfig> src/backups/scheduled-backup.test.ts (code/activation addsrc/bootstrap/activation-receipts-measure.test.ts). Modes pg/sqlite/newest/cross/code/activation/repeat/digest/overlap all EXIT1 with DRILL_APPLIED+exactanchorcount. Use-t'real PostgreSQL backup restore' forpg, 'scheduled backups|backup retention' forcode, 'refuses activation with' foractivation, correspondingtesttitle forothers. Actualsourcefiles/hashproofinothercomment. Fullconfig:
const cases = {
 newest: ['bootstrap/activation-receipts-measure.ts', 'stamped.slice(0, Math.max(0, stamped.length - BACKUP_RETENTION))', 'stamped.slice(BACKUP_RETENTION)'],
 cross: ['backups/scheduled-backup.ts', 'pruneBackups({ fs }, directory, state.ref)', 'pruneBackups({ fs }, directory.replace(SCHEDULED_BACKUP_LEAF, "pre-migration"), state.ref)'],
 pg: ['backups/backup-ports.ts', 'async function restoreDatabase(path: string): Promise<BackupProof> {', 'async function restoreDatabase(path: string): Promise<BackupProof> { return {sha256: await backupFileHash(path), restoredSha256: await backupFileHash(path)};'],
 sqlite: ['backups/backup-ports.ts', 'async function restoreStore(path: string): Promise<BackupProof> {', 'async function restoreStore(path: string): Promise<BackupProof> { return {sha256: await backupFileHash(path), restoredSha256: await backupFileHash(path)};'],
 code: ['bootstrap/activation-receipts-measure.ts', 'code: "BACKUP_FAILED" as const', 'code: "MUTATED_BACKUP_FAILED" as const'],
 activation: ['bootstrap/activation-receipts-measure.ts', 'if (pruning.failedRefs.length > 0) return unmeasuredReceipt("backup", "backup retention failed");', 'void pruning;'],
 repeat: ['backups/scheduled-backup.ts', 'if (existsSync(state.ref)) throw new Error("BACKUP_FAILED");', 'void state;'],
 digest: ['backups/backup-ports.ts', 'return hash.digest("hex");', 'return "0".repeat(64);'],
 overlap: ['backups/scheduled-backup.ts', 'mkdirSync(candidateLock); lock = candidateLock;', 'mkdirSync(candidateLock, { recursive: true }); lock = candidateLock;'],
};
export default { test: { fileParallelism: false, maxWorkers: 1 }, plugins: [{ name: 'backup-production-drill', enforce: 'pre', transform(source, id) {
 const entry = cases[process.env.MOE_BACKUP_DRILL];
 if (!entry || !id.replaceAll('\\', '/').endsWith('/' + entry[0])) return;
 const code = source.replaceAll('\r\n', '\n');
 if (code.split(entry[1]).length !== 2) throw new Error('DRILL_ANCHOR_COUNT_WRONG');
 console.log('DRILL_APPLIED ' + process.env.MOE_BACKUP_DRILL);
 return { code: code.replace(entry[1], entry[2]), map: null };
}}] };
